// src/GDAL7_driver.cpp
// Manual file - NOT generated by orchestrate.R
// Provides GDALDriver class methods

#include <cpl_minixml.h>

#include "gdal7.h"

namespace {

inline GDALDriverH driver(SEXP xp) {
    return gdal7::get<GDALDriverH>(xp, gdal7::Kind::Driver);
}

}  // namespace

// ============================================================================
// Driver info methods
// ============================================================================

[[cpp11::register]]
cpp11::strings GDAL7_driver_get_short_name(SEXP xp) {
    return gdal7::chr(GDALGetDriverShortName(driver(xp)));
}

[[cpp11::register]]
cpp11::strings GDAL7_driver_get_long_name(SEXP xp) {
    return gdal7::chr(GDALGetDriverLongName(driver(xp)));
}

[[cpp11::register]]
cpp11::strings GDAL7_driver_get_help_topic(SEXP xp) {
    return gdal7::chr(GDALGetDriverHelpTopic(driver(xp)));
}

// Recursively look for <Option name="..."> in a driver option list document.
static bool option_list_has(const CPLXMLNode* node, const char* option_name) {
    for (const CPLXMLNode* n = node; n != nullptr; n = n->psNext) {
        if (n->eType == CXT_Element && EQUAL(n->pszValue, "Option")) {
            const char* name = CPLGetXMLValue(const_cast<CPLXMLNode*>(n), "name", nullptr);
            if (name && EQUAL(name, option_name)) {
                return true;
            }
        }
        if (n->psChild && option_list_has(n->psChild, option_name)) {
            return true;
        }
    }
    return false;
}

// There is no GDALDriverHasOpenOption() in the GDAL C API, so this is answered
// from the driver's own DMD_OPENOPTIONLIST metadata, which every version has.
[[cpp11::register]]
bool GDAL7_driver_has_open_option(SEXP xp, std::string option_name) {
    GDALDriverH h = driver(xp);

    const char* xml = GDALGetMetadataItem(h, GDAL_DMD_OPENOPTIONLIST, nullptr);
    if (!xml || !*xml) {
        return false;
    }

    gdal7::ErrorScope err;
    CPLXMLNode* root = CPLParseXMLString(xml);
    if (!root) {
        // A driver with an unparseable option list is not worth an error;
        // the honest answer is that the option was not found.
        return false;
    }

    const bool found = option_list_has(root, option_name.c_str());
    CPLDestroyXMLNode(root);
    err.flush();
    return found;
}

// ============================================================================
// Dataset get_driver returns external pointer - need to wrap properly
// ============================================================================

[[cpp11::register]]
SEXP GDAL7_dataset_get_driver_ptr(SEXP xp) {
    GDALDatasetH h = gdal7::get<GDALDatasetH>(xp, gdal7::Kind::Dataset);

    // Drivers belong to GDAL's driver manager for the life of the process, so
    // this one is not tied to the dataset it was reached through.
    return gdal7::wrap(GDALGetDatasetDriver(h), gdal7::Kind::Driver);
}

// ============================================================================
// Top-level driver functions
// ============================================================================

[[cpp11::register]]
int GDAL7_get_driver_count() {
    return GDALGetDriverCount();
}

[[cpp11::register]]
SEXP GDAL7_get_driver_by_name(std::string name) {
    return gdal7::wrap(GDALGetDriverByName(name.c_str()), gdal7::Kind::Driver);
}

[[cpp11::register]]
SEXP GDAL7_get_driver(int index) {
    return gdal7::wrap(GDALGetDriver(index), gdal7::Kind::Driver);
}

// ============================================================================
// Driver capabilities - check metadata for DCAP_* flags
// ============================================================================

[[cpp11::register]]
bool GDAL7_driver_test_capability(SEXP xp, std::string capability) {
    // Check in driver metadata for DCAP_* entries
    const char* value = GDALGetMetadataItem(driver(xp), capability.c_str(), nullptr);
    return value != nullptr && EQUAL(value, "YES");
}

[[cpp11::register]]
cpp11::strings GDAL7_driver_get_creation_options(SEXP xp) {
    return gdal7::chr(GDALGetDriverCreationOptionList(driver(xp)));
}

// ============================================================================
// Get driver metadata item (inherits from MajorObject but need driver handle)
// ============================================================================

[[cpp11::register]]
cpp11::strings GDAL7_driver_get_metadata_item(SEXP xp, std::string name, std::string domain) {
    const char* value = GDALGetMetadataItem(driver(xp), name.c_str(),
                                            domain.empty() ? nullptr : domain.c_str());
    return gdal7::chr(value);
}
